#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }

# --room と日付を一緒に渡すと、両方で絞り込む
u=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\naoi\t2026-01-02\t13:00\t14:00\tz\nkaede\t2026-01-02\t09:00\t10:00\ty\n' > "$u"
[ "$(BOOKINGS=$u bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 13:00-14:00 aoi z' ] || { echo "list --room with date"; fail=1; }

# 値の無い --room は exit 2 と usage。stdout には何も出さない
err=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null); rc=$?
[ "$rc" = 2 ] && [ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room 2>/dev/null)" ] || { echo "list --room without value printed stdout"; fail=1; }

# 日付の形式が違えば exit 2 と bad date。stdout には何も出さない
for bad in 2026/11/10 2026-13-01 2026-11-32; do
  err=$(BOOKINGS=$t bash src/list.sh "$bad" 2>&1 >/dev/null); rc=$?
  [ "$rc" = 2 ] && [ "$err" = "bad date: $bad (expected YYYY-MM-DD)" ] || { echo "list bad date $bad"; fail=1; }
  [ -z "$(BOOKINGS=$t bash src/list.sh "$bad" 2>/dev/null)" ] || { echo "list bad date $bad printed stdout"; fail=1; }
done

rm -f "$t" "$u"; exit $fail

