#!/bin/bash
# list.sh [--room ROOM] [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
room=
has_room=0
if [ "${1:-}" = --room ]; then
  [ $# -ge 2 ] || { echo "usage: list.sh [--room ROOM] [DATE]" >&2; exit 2; }
  room=$2; has_room=1; shift 2
fi
d=${1:-}
if [ -n "$d" ] && ! [[ $d =~ ^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$ ]]; then
  echo "bad date: $d (expected YYYY-MM-DD)" >&2; exit 2
fi
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="$d" -v r="$room" -v hr="$has_room" 'NF && (d == "" || $2 == d) && (hr == 0 || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\naoi\t2026-01-02\t12:00\t13:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 12:00-13:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 12:00-13:00 aoi z' ] || { echo "list --room with date"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-01 --room aoi 2>/dev/null)" != "" ] || { echo "list date before --room should not be read as an option"; fail=1; }
e=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null); rc=$?
[ $rc = 2 ] && [ "$e" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
rm -f "$t"; exit $fail

