[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = "$(printf '2026-01-01 10:00-11:00 aoi x\n2026-01-02 14:00-15:00 aoi z')" ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room ao)" ] || { echo "list --room matched a prefix"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh --room 2>&1); rc=$?
[ "$rc" = 2 ] && [ "$out" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
out=$(BOOKINGS=$t bash src/list.sh 2026/11/10 2>&1); rc=$?
[ "$rc" = 2 ] && [ "$out" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date"; fail=1; }
rm -f "$t"; exit $fail

