#!/bin/bash
fail=0
t=$(mktemp); e=$(mktemp)
printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
run() { out=$(BOOKINGS=$t bash src/list.sh "$@" 2>"$e"); code=$?; err=$(cat "$e"); }

run --room aoi
[ "$out" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
run
[ "$out" = "$(printf '2026-01-01 09:00-10:00 kaede y\n2026-01-01 10:00-11:00 aoi x')" ] || { echo "list unchanged"; fail=1; }
run --room ao
[ -z "$out" ] || { echo "list --room matched a prefix"; fail=1; }

run --room aoi 2026-01-01
[ "$out" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room with date"; fail=1; }
run --room kaede 2026-01-01
[ "$out" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list --room with date"; fail=1; }
run --room aoi 2026-01-02
[ "$code" = 0 ] && [ -z "$out" ] || { echo "list --room with date and no match"; fail=1; }

run --room
[ "$code" = 2 ] && [ -z "$out" ] && [ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value"; fail=1; }
run --room ""
[ "$code" = 2 ] && [ -z "$out" ] || { echo "list --room with empty value"; fail=1; }
run aoi 2026-01-01 extra
[ "$code" = 2 ] && [ -z "$out" ] && [ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list with too many arguments"; fail=1; }

run 2026/11/10
[ "$code" = 2 ] && [ -z "$out" ] && [ "$err" = 'bad date: 2026/11/10 (expected YYYY-MM-DD)' ] || { echo "list bad date format"; fail=1; }
run 2026-13-01
[ "$code" = 2 ] && [ "$err" = 'bad date: 2026-13-01 (expected YYYY-MM-DD)' ] || { echo "list bad month"; fail=1; }
run 2026-01-32
[ "$code" = 2 ] && [ "$err" = 'bad date: 2026-01-32 (expected YYYY-MM-DD)' ] || { echo "list bad day"; fail=1; }
run --room aoi 2026/11/10
[ "$code" = 2 ] && [ -z "$out" ] || { echo "list --room with bad date"; fail=1; }

rm -f "$t" "$e"; exit $fail

